#include "solver.h"
#include "dimacs.h"
#include <assert.h>
#include <stdio.h>
int main(void) {
    SolverOpts o=default_opts();o.equiv=true;o.probing=false;o.max_conflicts=1;
    Solver *s=solver_new_with_opts(&o);assert(s);
    assert(dimacs_parse_string(s,"p cnf 6 4\n-4 5 0\n4 -5 0\n1 6 2 0\n1 6 -2 0\n")==DIMACS_OK);
    lbool result=solver_solve(s);assert(!s->error && result==UNDEF);
    assert(s->stats.equiv_variables==1 && s->num_learnts==1);
    printf("{\"substituted\":%llu,\"levels_capacity\":%u,\"level_seen_present\":%s,\"learned_size\":%u,\"learned_lbd\":%u,\"max_lbd\":%llu}\n",(unsigned long long)s->stats.equiv_variables,s->levels_capacity,s->level_seen?"true":"false",CLAUSE_SIZE(s->arena,s->learnts[0]),clause_lbd(s->arena,s->learnts[0]),(unsigned long long)s->stats.max_lbd);
    solver_free(s);return 0;
}
